const STORAGE_KEY = "ipi_prospecting_tool_state_v1";
const VIEW_KEY = "ipi_prospecting_tool_saved_views_v1";
const STATUS_OPTIONS = ["Unreviewed","Review Complete","Priority Target","Outreach Ready","In Contact","Nurture","Not a Fit"];

const state = {
  filters: {
    search: "",
    minScore: 0,
    tiers: new Set(),
    vendors: new Set(),
    services: new Set(),
    confidence: new Set(),
    missingTurnoverOnly: false,
    missingLinkedInOnly: false,
    missingNotesOnly: false,
    priorityOnly: false,
    status: ""
  },
  sort: { key: "weightedScore", dir: "desc" },
  activeView: "prospects",
  activePartnerName: null,
  meta: loadMeta(),
  savedViews: loadSavedViews()
};

function loadMeta(){
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch(err) { return {}; }
}
function persistMeta(){ localStorage.setItem(STORAGE_KEY, JSON.stringify(state.meta)); }

function loadSavedViews(){
  try {
    const raw = localStorage.getItem(VIEW_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch(err) { return {}; }
}
function persistSavedViews(){ localStorage.setItem(VIEW_KEY, JSON.stringify(state.savedViews)); }

function slug(text){ return String(text || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
function formatScore(score){ return Number(score).toFixed(2); }
function formatTurnover(value){
  if (value === null || value === undefined || value === "") return "—";
  return `£${Number(value).toFixed(Number(value) % 1 === 0 ? 0 : 1)}m`;
}
function formatEmployees(value, raw){
  if (raw) return String(raw);
  if (value === null || value === undefined || value === "") return "—";
  return String(value);
}
function getTierClass(tier){
  if (tier.includes("Tier 1")) return "tier1";
  if (tier.includes("Tier 2")) return "tier2";
  if (tier.includes("Tier 3")) return "tier3";
  return "tier4";
}
function getConfidenceRank(value){ return { High:3, Medium:2, Low:1 }[value] || 0; }
function getMeta(name){
  if (!state.meta[name]) state.meta[name] = { status:"Unreviewed", priority:false, note:"" };
  return state.meta[name];
}
function setMeta(name, patch){
  state.meta[name] = { ...getMeta(name), ...patch };
  persistMeta();
}
function getPartnerByName(name){ return PARTNERS.find(p => p.name === name); }

function getAllOptions(field){
  const values = new Set();
  PARTNERS.forEach(p => (p[field] || []).forEach(v => values.add(v)));
  return Array.from(values).sort((a,b)=>a.localeCompare(b));
}

function escapeHtml(value){
  return String(value ?? "")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;");
}
function escapeAttr(value){ return escapeHtml(value).replaceAll("'","&#39;"); }

function createChecks(containerId, values, setRef){
  const el = document.getElementById(containerId);
  el.innerHTML = values.map(v => `
    <label class="check">
      <input type="checkbox" value="${escapeHtml(v)}" />
      <span>${escapeHtml(v)}</span>
    </label>
  `).join("");
  el.querySelectorAll("input").forEach(input => {
    input.addEventListener("change", () => {
      if (input.checked) setRef.add(input.value);
      else setRef.delete(input.value);
      renderAll();
    });
  });
}

function syncCheckboxGroup(containerId, values){
  document.querySelectorAll(`#${containerId} input`).forEach(input => { input.checked = values.has(input.value); });
}

function bindFilters(){
  createChecks("tierFilters", ["Tier 1 – Strategic Target","Tier 2 – Strong Prospect","Tier 3 – Opportunistic","Tier 4 – Low Priority"], state.filters.tiers);
  createChecks("vendorFilters", getAllOptions("vendors"), state.filters.vendors);
  createChecks("serviceFilters", getAllOptions("services"), state.filters.services);
  createChecks("confidenceFilters", ["High","Medium","Low"], state.filters.confidence);

  document.getElementById("globalSearch").addEventListener("input", e => {
    state.filters.search = e.target.value.trim().toLowerCase();
    renderAll();
  });

  document.getElementById("minScore").addEventListener("input", e => {
    state.filters.minScore = Number(e.target.value);
    document.getElementById("minScoreValue").value = Number(e.target.value).toFixed(1);
    renderAll();
  });
  document.getElementById("minScoreValue").value = "0.0";

  ["missingTurnoverOnly","missingLinkedInOnly","missingNotesOnly","priorityOnly"].forEach(id => {
    document.getElementById(id).addEventListener("change", e => {
      state.filters[id] = e.target.checked;
      renderAll();
    });
  });

  document.getElementById("statusFilter").addEventListener("change", e => {
    state.filters.status = e.target.value;
    renderAll();
  });

  document.getElementById("resetFiltersBtn").addEventListener("click", resetFilters);
  document.getElementById("refreshBtn").addEventListener("click", renderAll);
  document.getElementById("exportBtn").addEventListener("click", exportCurrentView);
  document.getElementById("saveViewBtn").addEventListener("click", saveCurrentView);
  document.getElementById("savedViews").addEventListener("change", e => {
    if (e.target.value) applySavedView(e.target.value);
  });

  document.querySelectorAll(".tab").forEach(btn => {
    btn.addEventListener("click", () => {
      state.activeView = btn.dataset.view;
      document.querySelectorAll(".tab").forEach(t => t.classList.toggle("active", t === btn));
      document.querySelectorAll(".view").forEach(view => view.classList.toggle("active", view.id === `view-${btn.dataset.view}`));
    });
  });

  document.querySelectorAll("th[data-sort]").forEach(th => {
    th.addEventListener("click", () => {
      const map = { routeToRevenue:"scoring.routeToRevenue.score", vendor:"scoring.vendor.score" };
      const key = map[th.dataset.sort] || th.dataset.sort;
      if (state.sort.key === key) state.sort.dir = state.sort.dir === "asc" ? "desc" : "asc";
      else {
        state.sort.key = key;
        state.sort.dir = key === "name" ? "asc" : "desc";
      }
      renderAll();
    });
  });

  document.getElementById("drawerClose").addEventListener("click", closeDrawer);
}

function resetFilters(){
  state.filters.search = "";
  state.filters.minScore = 0;
  state.filters.tiers = new Set();
  state.filters.vendors = new Set();
  state.filters.services = new Set();
  state.filters.confidence = new Set();
  state.filters.missingTurnoverOnly = false;
  state.filters.missingLinkedInOnly = false;
  state.filters.missingNotesOnly = false;
  state.filters.priorityOnly = false;
  state.filters.status = "";
  document.getElementById("globalSearch").value = "";
  document.getElementById("minScore").value = 0;
  document.getElementById("minScoreValue").value = "0.0";
  ["missingTurnoverOnly","missingLinkedInOnly","missingNotesOnly","priorityOnly"].forEach(id => document.getElementById(id).checked = false);
  document.getElementById("statusFilter").value = "";
  document.querySelectorAll(".sidebar input[type=checkbox]").forEach(i => { if (!i.id) i.checked = false; });
  document.getElementById("savedViews").value = "";
  renderAll();
}

function saveCurrentView(){
  const name = prompt("Save current view as");
  if (!name) return;
  state.savedViews[name] = {
    filters: {
      search: state.filters.search,
      minScore: state.filters.minScore,
      tiers: Array.from(state.filters.tiers),
      vendors: Array.from(state.filters.vendors),
      services: Array.from(state.filters.services),
      confidence: Array.from(state.filters.confidence),
      missingTurnoverOnly: state.filters.missingTurnoverOnly,
      missingLinkedInOnly: state.filters.missingLinkedInOnly,
      missingNotesOnly: state.filters.missingNotesOnly,
      priorityOnly: state.filters.priorityOnly,
      status: state.filters.status
    },
    sort: state.sort
  };
  persistSavedViews();
  populateSavedViews(name);
}

function applySavedView(name){
  const view = state.savedViews[name];
  if (!view) return;
  resetFilters();
  state.filters.search = view.filters.search || "";
  state.filters.minScore = Number(view.filters.minScore || 0);
  state.filters.tiers = new Set(view.filters.tiers || []);
  state.filters.vendors = new Set(view.filters.vendors || []);
  state.filters.services = new Set(view.filters.services || []);
  state.filters.confidence = new Set(view.filters.confidence || []);
  state.filters.missingTurnoverOnly = !!view.filters.missingTurnoverOnly;
  state.filters.missingLinkedInOnly = !!view.filters.missingLinkedInOnly;
  state.filters.missingNotesOnly = !!view.filters.missingNotesOnly;
  state.filters.priorityOnly = !!view.filters.priorityOnly;
  state.filters.status = view.filters.status || "";
  state.sort = view.sort || { key:"weightedScore", dir:"desc" };

  document.getElementById("globalSearch").value = state.filters.search;
  document.getElementById("minScore").value = state.filters.minScore;
  document.getElementById("minScoreValue").value = Number(state.filters.minScore).toFixed(1);
  ["missingTurnoverOnly","missingLinkedInOnly","missingNotesOnly","priorityOnly"].forEach(id => document.getElementById(id).checked = !!state.filters[id]);
  document.getElementById("statusFilter").value = state.filters.status;
  syncCheckboxGroup("tierFilters", state.filters.tiers);
  syncCheckboxGroup("vendorFilters", state.filters.vendors);
  syncCheckboxGroup("serviceFilters", state.filters.services);
  syncCheckboxGroup("confidenceFilters", state.filters.confidence);
  renderAll();
}

function populateSavedViews(selected=""){
  const select = document.getElementById("savedViews");
  const names = Object.keys(state.savedViews).sort((a,b)=>a.localeCompare(b));
  select.innerHTML = `<option value="">Saved views</option>` + names.map(name => `<option value="${escapeHtml(name)}" ${selected===name?'selected':''}>${escapeHtml(name)}</option>`).join("");
}

function resolve(path, obj){ return path.split(".").reduce((acc, part) => acc && acc[part], obj); }

function filterPartners(){
  return PARTNERS.filter(partner => {
    const meta = getMeta(partner.name);
    const haystack = [
      partner.name, partner.locationCity, partner.locationState, partner.additionalInfo,
      ...(partner.vendors || []), ...(partner.services || []), ...(partner.industries || [])
    ].join(" ").toLowerCase();

    if (state.filters.search && !haystack.includes(state.filters.search)) return false;
    if (partner.weightedScore < state.filters.minScore) return false;
    if (state.filters.tiers.size && !state.filters.tiers.has(partner.tier)) return false;
    if (state.filters.vendors.size && !(partner.vendors || []).some(v => state.filters.vendors.has(v))) return false;
    if (state.filters.services.size && !(partner.services || []).some(v => state.filters.services.has(v))) return false;
    if (state.filters.confidence.size && !state.filters.confidence.has(partner.confidence)) return false;
    if (state.filters.missingTurnoverOnly && !partner.dataQuality.missingTurnover) return false;
    if (state.filters.missingLinkedInOnly && !partner.dataQuality.missingLinkedIn) return false;
    if (state.filters.missingNotesOnly && !partner.dataQuality.missingNotes) return false;
    if (state.filters.priorityOnly && !meta.priority) return false;
    if (state.filters.status && meta.status !== state.filters.status) return false;
    return true;
  });
}

function sortPartners(items){
  const dir = state.sort.dir === "asc" ? 1 : -1;
  return [...items].sort((a,b) => {
    let va = resolve(state.sort.key, a);
    let vb = resolve(state.sort.key, b);
    if (state.sort.key === "confidence") {
      va = getConfidenceRank(a.confidence); vb = getConfidenceRank(b.confidence);
    }
    if (state.sort.key === "tier") {
      va = Number(a.tier.match(/Tier (\d)/)?.[1] || 9);
      vb = Number(b.tier.match(/Tier (\d)/)?.[1] || 9);
    }
    if (va === null || va === undefined || va === "") va = -999999;
    if (vb === null || vb === undefined || vb === "") vb = -999999;
    if (typeof va === "string" || typeof vb === "string") return String(va).localeCompare(String(vb)) * dir;
    return (va - vb) * dir;
  });
}

function average(arr){ return arr.length ? arr.reduce((sum, n) => sum + Number(n), 0) / arr.length : 0; }

function renderKPIs(filtered){
  const kpis = [
    { label:"Total Partners", value: filtered.length, meta:"Current filtered result set", icon:"📊", click: () => resetFilters() },
    { label:"Tier 1", value: filtered.filter(p => p.tier.includes("Tier 1")).length, meta:"Strategic targets in view", icon:"🎯", click: () => { resetFilters(); state.filters.tiers.add("Tier 1 – Strategic Target"); syncCheckboxGroup("tierFilters", state.filters.tiers); renderAll(); } },
    { label:"Tier 2", value: filtered.filter(p => p.tier.includes("Tier 2")).length, meta:"Strong prospects in view", icon:"📈" },
    { label:"Legacy Wedge", value: filtered.filter(p => p.scoring.vendor.score >= 5).length, meta:"Legacy vendor displacement", icon:"🔁" },
    { label:"Missing Data", value: filtered.filter(p => p.dataQuality.missingTurnover || p.dataQuality.missingLinkedIn || p.dataQuality.missingNotes).length, meta:"Records needing cleanup", icon:"🧹" },
    { label:"Avg Score", value: filtered.length ? average(filtered.map(p => p.weightedScore)).toFixed(2) : "0.00", meta:"Weighted average score", icon:"⚖️" }
  ];
  document.getElementById("kpiRow").innerHTML = kpis.map((k, idx) => `
    <div class="kpi" data-kpi="${idx}">
      <div class="top"><span>${k.label}</span><span>${k.icon}</span></div>
      <div class="value">${k.value}</div>
      <div class="meta">${k.meta}</div>
    </div>
  `).join("");
  document.querySelectorAll(".kpi").forEach((el, idx) => { if (typeof kpis[idx].click === "function") el.addEventListener("click", kpis[idx].click); });
}

function prettySortLabel(key){
  return {
    weightedScore:"score",
    name:"name",
    tier:"tier",
    locationCity:"location",
    employees:"scale",
    "scoring.routeToRevenue.score":"route-to-revenue",
    "scoring.vendor.score":"vendor"
  }[key] || key;
}

