function closeDrawer(){ document.getElementById("drawer").classList.remove("open"); }

function csvEscape(value){
  const s = String(value ?? "");
  return `"${s.replaceAll('"', '""')}"`;
}
function exportCurrentView(){
  const rows = sortPartners(filterPartners());
  const headers = ["Name","Tier","Weighted Score","Confidence","Route-to-Revenue","Vendor","Customer","Sales","Scale","Geo","City","State","Website","LinkedIn","Priority","Status","Note"];
  const csvRows = [
    headers.join(","),
    ...rows.map(p => {
      const meta = getMeta(p.name);
      return [
        csvEscape(p.name),
        csvEscape(p.tier),
        p.weightedScore,
        csvEscape(p.confidence),
        csvEscape(p.scoring.routeToRevenue.label),
        csvEscape(p.scoring.vendor.label),
        csvEscape(p.scoring.customer.label),
        csvEscape(p.scoring.sales.label),
        csvEscape(p.scoring.scale.label),
        csvEscape(p.scoring.geo.label),
        csvEscape(p.locationCity),
        csvEscape(p.locationState),
        csvEscape(normalizeUrl(p.website)),
        csvEscape(normalizeUrl(p.linkedin)),
        meta.priority ? "Yes" : "No",
        csvEscape(meta.status),
        csvEscape(meta.note || "")
      ].join(",");
    })
  ].join("\n");

  const blob = new Blob([csvRows], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "ipi_prospecting_export.csv";
  a.click();
  URL.revokeObjectURL(url);
}

function renderAll(){
  const filtered = sortPartners(filterPartners());
  renderKPIs(filtered);
  renderTable(filtered);
  renderCurrentViewStats(filtered);
  renderQualityView();
  if (state.activePartnerName && document.getElementById("drawer").classList.contains("open")) openDrawer(state.activePartnerName);
}

bindFilters();
populateSavedViews();
renderAll();
